const out = [{ payload: { clear: 'black' } }];
const bars = ['white', 'yellow', 'cyan', 'green', 'magenta', 'red', 'blue', 'black'];
bars.forEach((c, i) => out.push({ payload: { rect: { x: i * 12, y: 2, w: 12, h: 30, color: c, fill: true } } }));
for (let x = 0; x < 96; x++) { const g = Math.round(x * 255 / 95); out.push({ payload: { rect: { x, y: 34, w: 1, h: 26, color: [g, g, g], fill: true } } }); }
out.push({ payload: { rect: { x: 0, y: 0, w: 96, h: 64, color: 'white' } } });
out.push({ payload: { show: true } });
out.push({ payload: { scroll: { horizontal: 1, startRow: 0, rows: 64, vertical: 0, interval: 0 } } });
return [out];
